"use client";
import { Card } from "@/components/ui/card";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { useState } from "react";

const mockAppointments = [
  {
    id: 1,
    doctor: {
      name: "Dr. Jane Smith",
      avatar: "/public/globe.svg",
      specialization: "Cardiologist",
    },
    date: "2024-06-10T14:00:00Z",
    status: "Confirmed",
    type: "Upcoming",
  },
  {
    id: 2,
    doctor: {
      name: "Dr. John Doe",
      avatar: "/public/window.svg",
      specialization: "Dermatologist",
    },
    date: "2024-05-01T09:30:00Z",
    status: "Cancelled",
    type: "Past",
  },
  {
    id: 3,
    doctor: {
      name: "Dr. Alice Brown",
      avatar: "/public/file.svg",
      specialization: "Pediatrician",
    },
    date: "2024-06-15T11:00:00Z",
    status: "Pending",
    type: "Upcoming",
  },
];

const statusColors = {
  Confirmed: "bg-green-100 text-green-700",
  Pending: "bg-yellow-100 text-yellow-700",
  Cancelled: "bg-red-100 text-red-700",
};

function formatDate(dateStr) {
  const date = new Date(dateStr);
  return date.toLocaleString(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  });
}

export default function AppointmentsPage() {
  const [tab, setTab] = useState("Upcoming");
  const filtered = mockAppointments.filter((a) => a.type === tab);

  return (
    <div className="max-w-2xl mx-auto p-4">
      <h1 className="text-2xl font-bold mb-6">My Appointments</h1>
      <Tabs value={tab} onValueChange={setTab} className="mb-6">
        <TabsList className="w-full flex gap-2 bg-gray-50 rounded-xl">
          <TabsTrigger value="Upcoming" className="flex-1">Upcoming</TabsTrigger>
          <TabsTrigger value="Past" className="flex-1">Past</TabsTrigger>
        </TabsList>
      </Tabs>
      <div className="space-y-4">
        {filtered.length === 0 && (
          <div className="text-center text-gray-500 py-8">No {tab.toLowerCase()} appointments.</div>
        )}
        {filtered.map((appt) => (
          <Card key={appt.id} className="rounded-xl shadow p-4 flex flex-col gap-4">
            <div className="flex items-center gap-4">
              <Avatar src={appt.doctor.avatar} alt={appt.doctor.name} className="w-12 h-12" />
              <div className="flex-1">
                <div className="font-semibold text-base">{appt.doctor.name}</div>
                <div className="text-sm text-gray-500">{appt.doctor.specialization}</div>
              </div>
              <Badge className={`text-sm px-3 py-1 ${statusColors[appt.status]}`}>{appt.status}</Badge>
            </div>
            <Separator />
            <div className="flex items-center justify-between">
              <Badge className="bg-blue-100 text-blue-700 text-xs px-2 py-1 rounded">{formatDate(appt.date)}</Badge>
              <div className="flex gap-2">
                {appt.status === "Confirmed" && tab === "Upcoming" && (
                  <Button size="sm" className="rounded shadow text-sm hover:bg-gray-100">Join Video</Button>
                )}
                {appt.status !== "Cancelled" && tab === "Upcoming" && (
                  <Button size="sm" variant="outline" className="rounded text-sm hover:bg-gray-100">Cancel</Button>
                )}
              </div>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
} 